import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import type * as ast from "../ast/index.ts";

// Vectors are generated by ts/tools/gen-parse-autolink-vectors: parse.Inline of the real Go package on inline
// Markdown that exercises auto_link.go, inline_html.go, html_text_style.go and html_text_style_inline.go.
// Each vector is [[optionsName, markdownHex], dumpOfTree] or [args, null, true] when Go panicked.
//
// This test needs the whole parse package, which is owned by several porting groups, so it is imported
// dynamically; when the import fails the test is skipped with the reason.

type Vec = [[string, string], unknown, boolean?];

const raw = JSON.parse(readFileSync(new URL("./testdata/autolink_vectors.json", import.meta.url), "utf8")) as Record<string, unknown>;
const vectors = raw.inline as Vec[];

function toHex(b: Uint8Array | null): string {
  return b === null ? "" : Buffer.from(b.buffer, b.byteOffset, b.length).toString("hex");
}

function dumpNode(n: ast.Node): unknown[] {
  const ial: string[] = [];
  for (const kv of n.KramdownIAL ?? []) {
    ial.push(kv[0] + "=" + kv[1]);
  }
  const children: unknown[] = [];
  for (let c = n.FirstChild; c !== null; c = c.Next) {
    children.push(dumpNode(c));
  }
  return [n.Type, toHex(n.Tokens), n.LinkType, n.TextMarkType, n.TextMarkAHref, n.TextMarkATitle, n.TextMarkTextContent, ial.join("\x1f"), toHex(n.HtmlEntityTokens), children];
}

let parse: typeof import("./index.ts") | null = null;
let importError = "";
try {
  parse = await import("./index.ts");
} catch (e) {
  importError = String(e);
}

function optionsByName(name: string) {
  const o = parse!.NewOptions();
  switch (name) {
    case "gfm":
      o.GFMAutoLink = true;
      break;
    case "protyle":
      o.GFMAutoLink = true;
      o.ProtyleWYSIWYG = true;
      o.ProtyleWYSIWYGAutoLink = true;
      o.HTMLTag2TextMark = true;
      o.KramdownSpanIAL = true;
      break;
    case "protyle-keep":
      o.ProtyleWYSIWYG = true;
      o.HTMLTag2TextMark = true;
      o.KramdownSpanIAL = true;
      o.KeepEscaped = true;
      break;
    case "vditor":
      o.VditorWYSIWYG = true;
      o.GFMAutoLink = true;
      break;
    case "ir":
      o.VditorIR = true;
      break;
  }
  return o;
}

if (parse === null) {
  test("parse.Inline on autolink and inline HTML inputs", { skip: `import failed: ${importError}` }, () => {});
} else {
  test("parse.Inline on autolink and inline HTML inputs", () => {
    assert.ok(vectors.length >= 500);
    const failures: string[] = [];
    let panics = 0;
    for (const v of vectors) {
      const [optName, mdHex] = v[0];
      const md = new Uint8Array(Buffer.from(mdHex, "hex"));
      const label = `${optName} ${JSON.stringify(Buffer.from(mdHex, "hex").toString("utf8"))}`;
      if (v[2] === true) {
        panics++;
        try {
          parse!.Inline("", md, optionsByName(optName));
          failures.push(`${label}: Go panicked, TypeScript did not`);
        } catch {
          // expected
        }
        continue;
      }
      try {
        const got = dumpNode(parse!.Inline("", md, optionsByName(optName)).Root!);
        if (JSON.stringify(got) !== JSON.stringify(v[1])) {
          failures.push(`${label}\n  got  ${JSON.stringify(got)}\n  want ${JSON.stringify(v[1])}`);
        }
      } catch (e) {
        failures.push(`${label}: TypeScript threw ${String(e)}`);
      }
    }
    assert.ok(panics >= 1, "the corpus contains Go panics");
    assert.deepStrictEqual(failures.slice(0, 5), [], `${failures.length} of ${vectors.length} vectors differ`);
  });
}
